parameters.jsCode:
const rows = $json.data || [];
return rows.map((p) => ({
  json: {
    paso_id: p.id,
    paso_documentId: p.documentId,
    nombre_oficial: p.nombre_oficial,
    codigo_fuente: p.codigo_fuente,
    region: p.region,
    latitud: p.latitud,
    longitud: p.longitud,
    altitud: p.altitud
  }
}));

const paso = $('Loop Pasos').item.json;
const climaResp = $('GET Clima Actual Paso').item.json;
const estadosResp = $('GET Estados Recientes').item.json;
const alertasResp = $('GET Alertas Vigentes').item.json;

const clima = climaResp.data?.[0] || null;
const estados = estadosResp.data || [];
const alertas = alertasResp.data || [];

function normEstado(e) {
  const raw = (e?.estado_normalizado || e?.estado_general || '').toString().toLowerCase();
  if (raw.includes('cerr')) return 'cerrado';
  if (raw.includes('precau') || raw.includes('habilitado con precauc')) return 'precaucion';
  if (raw.includes('hab') || raw.includes('abierto')) return 'habilitado';
  if (raw.includes('suspend')) return 'suspendido';
  return 'desconocido';
}

function riskLabel(prob) {
  if (prob >= 0.66) return 'Alto';
  if (prob >= 0.36) return 'Medio';
  return 'Bajo';
}

function predictedState(prob) {
  if (prob >= 0.75) return 'Cerrado';
  if (prob >= 0.45) return 'Precaucion';
  return 'Normal';
}

function clamp(n, min, max) {
  return Math.max(min, Math.min(max, n));
}

const hist = estados.map(e => ({
  estado: normEstado(e),
  motivo: (e.motivo_normalizado || e.motivo_estado || '').toString().toLowerCase(),
  fecha: e.fecha_reporte
}));

const cierres7d = hist.slice(0, 7).filter(x => x.estado === 'cerrado' || x.estado === 'suspendido').length;
const prec7d = hist.slice(0, 7).filter(x => x.estado === 'precaucion').length;
const ultimoEstado = hist[0]?.estado || 'desconocido';
const alertaVigente = alertas.length > 0;

const forecast = clima?.pronostico_3dias || {};
const dias = [
  { h: 24, d: forecast.d1 || null },
  { h: 48, d: forecast.d2 || null },
  { h: 72, d: forecast.d3 || null },
];

const out = [];

for (const item of dias) {
  const d = item.d || {};

  const tempMin = Number(d.temp_min ?? clima?.temperatura_actual ?? 0);
  const precip = Number(d.precipitacion_total ?? clima?.precipitacion_actual ?? 0);
  const viento = Number(d.viento_max ?? clima?.viento_actual ?? 0);
  const weathercode = Number(d.weathercode_dominante ?? clima?.weathercode ?? 0);

  let score = 0;
  const motivos = [];

  if ([71,73,75,77,85,86].includes(weathercode)) {
    score += 25;
    motivos.push('nieve pronosticada');
  }

  if ([95,96,99].includes(weathercode)) {
    score += 20;
    motivos.push('tormenta pronosticada');
  }

  if (precip >= 10) {
    score += 15;
    motivos.push('precipitacion alta');
  } else if (precip >= 4) {
    score += 8;
    motivos.push('precipitacion moderada');
  }

  if (viento >= 60) {
    score += 15;
    motivos.push('viento fuerte');
  } else if (viento >= 40) {
    score += 8;
    motivos.push('viento moderado');
  }

  if (tempMin <= -5) {
    score += 12;
    motivos.push('temperatura minima muy baja');
  } else if (tempMin <= 0) {
    score += 6;
    motivos.push('temperatura bajo cero');
  }

  if (Number(paso.altitud || 0) >= 2500) {
    score += 8;
    motivos.push('paso de alta montana');
  }

  if (ultimoEstado === 'cerrado' || ultimoEstado === 'suspendido') {
    score += 18;
    motivos.push('ultimo estado desfavorable');
  } else if (ultimoEstado === 'precaucion') {
    score += 10;
    motivos.push('ultimo estado con precaucion');
  }

  if (cierres7d >= 3) {
    score += 15;
    motivos.push('historial reciente de cierres');
  } else if (cierres7d >= 1) {
    score += 8;
    motivos.push('cierres recientes');
  }

  if (prec7d >= 2) {
    score += 8;
    motivos.push('antecedentes recientes de precaucion');
  }

  if (alertaVigente) {
    score += 10;
    motivos.push('alerta vigente');
  }

  score = clamp(score, 0, 100);
  const prob = clamp(score / 100, 0.05, 0.95);

  out.push({
    json: {
      paso_id: paso.paso_id,
      paso_documentId: paso.paso_documentId,
      nombre_oficial: paso.nombre_oficial,
      horizonte_horas: item.h,
      probabilidad: Number(prob.toFixed(2)),
      nivel_riesgo: riskLabel(prob),
      estado_predicho: predictedState(prob),
      motivo_resumen: motivos.slice(0, 4).join(', ') || 'sin senales relevantes',
      fecha_calculo: new Date().toISOString(),
      valido_desde: new Date().toISOString(),
      valido_hasta: new Date(Date.now() + item.h * 60 * 60 * 1000).toISOString(),
      modelo_version: 'risk-v1-rules',
      tipo_evento: 'prediccion_operativa',
      datos_entrada: {
        altitud: paso.altitud,
        ultimo_estado: ultimoEstado,
        cierres_7d: cierres7d,
        precaucion_7d: prec7d,
        alerta_vigente: alertaVigente,
        weathercode,
        temp_min: tempMin,
        precipitacion_total: precip,
        viento_max: viento
      }
    }
  });
}

return out;

